import{z as l,x as A,o as e,c as s,q as t,j as r,D as E,d as i,s as B,S as o}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"向量化与事件驱动的取舍","description":"","frontmatter":{"title":"向量化与事件驱动的取舍","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bf-vectorized-vs-event.md","filePath":"quant/bf-vectorized-vs-event.md","lastUpdated":1791413859000}'),d={name:"quant/bf-vectorized-vs-event.md"};function p(h,a,c,m,_,u){const n=A("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="向量化与事件驱动的取舍" tabindex="-1">向量化与事件驱动的取舍 <a class="header-anchor" href="#向量化与事件驱动的取舍" aria-label="Permalink to &quot;向量化与事件驱动的取舍&quot;">​</a></h1><div class="epigraph"><p>向量化回答「信号有没有」，事件驱动回答「这笔交易做不做得成」；把两问混进同一条净值曲线，两边的答案都失真。</p><footer>—— 据 López de Prado, Advances in Financial Machine Learning, 2018 对回测结构与路径依赖的论述；对照 Pardo 的仿真分层实践整理</footer></div><p><a href="/quant/bf-event-driven-anatomy">上一课</a>把框架拆成七个器官，其中撮合器与账本只在事件侧存在。缺口随之而来：研究要扫几千个候选，事件引擎每个候选慢几个数量级，全塞进事件侧算不起，全留在向量化侧又丢掉成交的路径依赖。本课写这条边界的画法：什么问题必须事件侧回答，什么问题允许向量化近似，两层如何对拍、差异归给谁。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>向量化的本质是把「当时能否成交」压缩成一组解析假设：下一根开盘价或中点加价差、无条件成交、现金无限。日频、满仓、低换手的因子研究里这组假设误差小、速度快一个数量级以上；但<a href="/quant/backtest-vectorization">回测向量化</a>已经指出，A 股 T+1 与涨跌停能让单列持仓矩阵直接非法，<a href="/quant/halt-limit-backtest">停牌与涨跌停对回测</a>里「在不可交易的 bar 上成交」是向量化最常造假的位置。取舍错的症状有两种：在向量化的漂亮夏普上晋级，实盘完成率远低于一；反过来，把还在筛选期的信号全灌进事件引擎，算力花在两周后就会被丢弃的候选上。</p><h3 id="判据与分工" tabindex="-1">判据与分工 <a class="header-anchor" href="#判据与分工" aria-label="Permalink to &quot;判据与分工&quot;">​</a></h3><p>判据一条：损益是否路径依赖。持仓转移成本、部分成交、拒单、限额、日内时序影响净值，就必须事件侧；信号统计本身（IC、分层收益、候选排序）允许向量化。分工因此是两层：研究层向量化粗筛并解析扣费，候选集合冻结后整批进事件层定案；冻结之前事件层不算任何信号，否则算力诱惑会重新打开「看一眼结果再改」的循环。</p>',7)),(e(),r(o,null,{default:E(()=>[B(n,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E4%BF%A1%E5%8F%B7%E7%A0%94%E7%A9%B6%20%E5%90%91%E9%87%8F%E5%8C%96%E7%B2%97%E7%AD%9B%22%5D%20--%3E%20FRZ%5B%22%E5%86%BB%E7%BB%93%E5%80%99%E9%80%89%E9%9B%86%E5%90%88%E4%B8%8E%20N%22%5D%0A%20%20FRZ%20--%3E%20EV%5B%22%E4%BA%8B%E4%BB%B6%E5%B1%82%E6%95%B4%E6%89%B9%E5%AE%9A%E6%A1%88%22%5D%0A%20%20EV%20--%3E%20CMP%7B%22%E4%B8%A4%E5%B1%82%E5%87%80%E5%80%BC%E5%B7%AE%E5%8F%AF%E8%A7%A3%E9%87%8A%3F%22%7D%0A%20%20CMP%20--%3E%7C%E6%98%AF%7C%20CAL%5B%22%E5%9B%9E%E5%86%99%E6%88%90%E6%9C%AC%E5%8F%82%E6%95%B0%E5%88%B0%E7%A0%94%E7%A9%B6%E5%B1%82%22%5D%0A%20%20CMP%20--%3E%7C%E5%90%A6%7C%20BUG%5B%22%E6%9F%A5%E5%BC%95%E6%93%8E%E4%B8%8E%E7%8A%B6%E6%80%81%E6%9C%BA%20%E4%B8%8D%E6%94%B9%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20CAL%20--%3E%20SIG%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对拍是两层之间的协议：同一份数据、同一版本信号，向量化在自报的成交假设下与事件引擎各跑一遍，净值差应能被假设逐项解释——价差多大、错过多少涨跌停、拒单多少笔。解释不了的残差才是引擎缺陷，修的是引擎或状态机，不是把信号朝事件层的结果方向调：那是把事件层当第三重交叉验证用，<a href="/quant/research-sim-prod">研究、模拟、实盘隔离</a>的警告原样适用。</p><p>成本参数的流向是单向的：事件层的实测（完成率、滑点分布）回写研究层的解析成本，让下一轮粗筛更接近真相；研究层不许因为向量化曲线好看而去「修」事件层。试验次数记在两层之和上，候选集合冻结后进事件层的那一批才算有效样本外。</p><p><span class="marginnote">算一笔数量级账：十年日频的向量化回测在笔记本上是毫秒级，事件引擎同一任务常以秒到分计，差距千倍上下。粗筛与定案分层不是风格偏好，是算力预算下的必然分工。</span></p><p><span class="marginnote">对拍的账要逐项算：两层净值差 \\(0.8\\%\\)，其中价差假设差贡献 \\(0.5\\%\\)、错过两个涨跌停贡献 \\(0.25\\%\\)、拒单贡献 \\(0.03\\%\\)，剩下的残差才轮到「查引擎」。跳过归因直接调参数，等于把缺陷当成了校准目标。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>两层能共存的前提是成交假设被显式化。向量化的成本函数与事件层的撮合器档位必须写成同一套参数（价差、冲击系数、拒单率），一层升级另一层随之校准；参数没有共享口径，差异既不能解释也不能收敛。事件层不是「更准的向量化」：它保留的是向量化没有的状态——在途订单、现金约束、会话边界——这些状态在低换手日频下多数时间不激活，这正是向量化的近似在那一域成立的原因。</p>',7)),(e(),r(o,null,{default:E(()=>[B(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E5%90%8C%E4%B8%80%E4%BF%A1%E5%8F%B7%20%E5%90%8C%E4%B8%80%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20V%5B%22%E5%90%91%E9%87%8F%E5%8C%96%E5%B1%82%20%E8%A7%A3%E6%9E%90%E5%81%87%E8%AE%BE%22%5D%0A%20%20S%20--%3E%20E%5B%22%E4%BA%8B%E4%BB%B6%E5%B1%82%20%E7%8A%B6%E6%80%81%E6%9C%BA%22%5D%0A%20%20V%20--%3E%20A1%5B%22%E4%B8%8B%E4%B8%80%E6%A0%B9%E5%BC%80%E7%9B%98%E4%BB%B7%E6%88%90%E4%BA%A4%22%5D%0A%20%20V%20--%3E%20A2%5B%22%E6%97%A0%E6%9D%A1%E4%BB%B6%E5%85%A8%E9%A2%9D%E6%88%90%E4%BA%A4%22%5D%0A%20%20E%20--%3E%20B1%5B%22%E5%9C%A8%E9%80%94%E8%AE%A2%E5%8D%95%E4%B8%8E%E9%83%A8%E5%88%86%E6%88%90%E4%BA%A4%22%5D%0A%20%20E%20--%3E%20B2%5B%22%E7%8E%B0%E9%87%91%E7%BA%A6%E6%9D%9F%E4%B8%8E%20T%2B1%22%5D%0A%20%20E%20--%3E%20B3%5B%22%E6%B6%A8%E8%B7%8C%E5%81%9C%E4%B8%8E%E5%81%9C%E7%89%8C%E6%8B%92%E6%88%90%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">术语翻译：「在途订单」就是已经发给柜台、但还没收到成交或拒绝回报的委托。向量化里不存在这个状态——它默认下单即成交；事件层必须记着它，否则同一份现金可能被下两单。两层差距在高换手策略上放大的根源就在这里。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不宣布向量化低人一等：中低频、无杠杆约束、成交假设不敏感的策略，向量化终身够用，事件层只在晋级关卡请出来。也不要把对拍做成常态校准——每轮都对到分毫不差，说明事件层被调得迁就假设，保真度反而在退化。混合策略（日频信号、日内执行）要求两层共享信号定义与时间戳语义，聚合口径必须版本化，见<a href="/quant/late-data-recon">时钟、迟到数据与对账</a>。</p><p><span class="marginnote">初学者容易把「两层对拍到分毫不差」当成工程质量高。方向恰恰反了：事件层若被调得迁就向量化假设，保真度正在退化——它存在的意义就是说出「这笔交易做不成」，偶尔对不上才是它在正常工作。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>判据一条：损益路径依赖必须事件侧；信号统计允许向量化粗筛。</li><li>分层流程：向量化粗筛、冻结候选与 \\(N\\)、事件层整批定案；事件层不做筛选期工作。</li><li>对拍差异逐项归因给成交假设；解释不了的残差是引擎缺陷，不是调信号的依据。</li><li>成本参数单向回写：事件层实测校准研究层假设，方向不可逆。</li><li>出处：López de Prado, <em>Advances in Financial Machine Learning</em>, Wiley, 2018；Pardo, <em>The Evaluation and Optimization of Trading Strategies</em>, 2007；站内<a href="/quant/backtest-vectorization">回测向量化</a>、<a href="/quant/halt-limit-backtest">停牌与涨跌停对回测</a>各课。</li></ul>',6))])}const D=l(d,[["render",p]]);export{C as __pageData,D as default};
